mapper.sql:
 FROM biz01_promo a
      INNER JOIN crd02_data b ON crd02_data_id = a.biz01_card_data_id
      LEFT OUTER JOIN LATERAL ( SELECT COUNT(*)                                                                  AS biz02_count
                                     , SUM(CASE WHEN COALESCE(biz02_emp_yn,'false') = 'true' THEN 1 ELSE 0 END) AS biz02_emp_count
                                  FROM biz02_person
                                 WHERE biz02_promo_id = biz01_promo_id
                              ) c ON TRUE
      LEFT OUTER JOIN act01_account_code d ON d.act01_account_code_id = a.biz01_account_code_id
      INNER JOIN crd01_card ON crd01_card_id = biz01_card_id
WHERE 1=1
  AND biz01_company_id = #{companyId}
  AND CAST(f_get_crdManagerId(biz01_card_id, biz01_provide_date) AS VARCHAR) LIKE #{managerId}||'%'
  AND biz01_std_ym = #{dataYm}
  AND COALESCE(biz01_provide_pur_cd,'%') LIKE #{providePurCode}
  AND CONCAT(crd02_franchise_nm,crd02_sector_nm, biz01_provide_company, biz01_note) ILIKE #{searchText}

mapper.select:
SELECT COALESCE(SUM(biz01_provide_amt), 0) FROM ( SELECT biz01_provide_amt , crd02_franchise_nm AS biz01_franchise_nm , crd02_sector_nm AS biz01_sector_nm , CASE WHEN COALESCE(act01_use_yn,'false') = 'false' THEN '(사용X)' ELSE '' END||act01_account_nm AS biz01_account_nm , crd01_card_nm AS biz01_html_card_nm , f_emp_kor_nm(crd03_person_id) AS biz01_reg_emp_nm , f_cdnm('ProvidePurCode' , biz01_provide_pur_cd , biz01_company_id, biz01_provide_date) AS biz01_provide_pur_nm , f_cdnm('ProvideContentCode' , biz01_provide_content_cd , biz01_company_id, biz01_provide_date) AS biz01_provide_content_nm FROM ( SELECT * FROM biz01_promo INNER JOIN crd02_data ON crd02_data_id = biz01_card_data_id INNER JOIN sys01_company ON sys01_company_id = biz01_company_id LEFT OUTER JOIN crd01_card ON crd01_card_id = biz01_card_id LEFT OUTER JOIN crd03_trans ON ( crd03_card_id = biz01_card_id AND biz01_provide_date BETWEEN crd03_fr_dt AND COALESCE(crd03_to_dt,'9999-12-31') ) LEFT OUTER JOIN act01_account_code ON (act01_account_code_id = biz01_account_code_id) WHERE biz01_company_id = #{companyId} AND COALESCE(biz01_provide_pur_cd,'%') LIKE #{providePurCode} AND biz01_std_ym = #{dataYm}
AND CASE WHEN #{managerId} = 0 THEN crd03_public_yn = 'true' ELSE ((CASE WHEN sys01_card_real_user_yn = 'true' THEN (CASE WHEN biz01_real_person_id IS NOT NULL THEN biz01_real_person_id ELSE crd03_person_id END) ELSE (CASE WHEN crd03_public_yn = 'true' THEN 0 ELSE crd03_person_id END) END ) = #{managerId}) END
) t ) tt WHERE 1=1 AND CONCAT( biz01_franchise_nm , biz01_sector_nm , biz01_account_nm , biz01_html_card_nm , biz01_reg_emp_nm , biz01_provide_pur_nm , biz01_provide_content_nm) ILIKE '%'||#{searchText}||'%'
